insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-tampontribe-organic-tampons', 'Tampon Tribe Organic Tampons', 'Tampon Tribe', 'tampon', 'physical', 'Certified organic cotton tampons with a biodegradable cardboard "twist" applicator and no plastic anywhere, including the packaging. The absorbent core is wrapped in an organic cotton "safety veil" that the brand says keeps loose cotton strands from being left behind. No rayon/viscose, perfume, dyes, or chlorine bleaching. Sold as a monthly subscription you can customize, pause, or cancel, with free U.S. delivery; the first box arrives in a reusable jute bag, refills in recycled paper.', '$10.60 per box, as a monthly subscription (Regular 16, Super 14, Super Plus 12, or a mixed or heavy-flow pack)', '/products/tampon-tribe/organic-tampons.webp', 'https://tampontribe.com/products/tampons', '["organic","sustainability","comfort","heavy-flow"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Tampons are regulated by the FDA as medical devices; tampontribe.com doesn’t list this product’s FDA clearance details. The manufacturer, Cohitech, is FDA-registered and certified to ISO 13485 (medical-device quality management).","materials":"100% organic cotton absorbent core and cover (certified organic under GOTS by ICEA) with an organic cotton safety veil around the core; biodegradable cardboard twist applicator with a rounded tip; paper wrapper. No superabsorbents, glue, rayon/viscose, perfume, or chlorine/dioxin bleaching.","recalls":"No recalls are mentioned on tampontribe.com; check current FDA and manufacturer recall notices.","allergens":"Hypoallergenic (independently dermatologist-tested, per manufacturer Cohitech), fragrance-free, dye-free, and vegan.","sideEffects":"Toxic shock syndrome (TSS) is rare but serious with any tampon: use the lowest absorbency you need and never wear one longer than 8 hours. Full warnings are listed below.","opinionAlerts":"Organic cotton avoids fragrance, dyes, and chlorine bleaching, but \"100% cotton\" isn’t automatically lower TSS risk: a 2018 lab study found cotton/rayon blend tampons grew less S. aureus than cotton-only ones. Absorbency and wear time matter most (FDA). Certification and testing: Tampon Tribe’s manufacturer, Cohitech (Spain), states its products are certified organic under GOTS by ICEA, and a June 2024 independent lab report (CALITEC LAB, Barcelona) found no pesticide residues, glyphosate, GMOs, formaldehyde, or detectable heavy metals in its organic cotton. Two limits: the lab tested a sample of raw organic cotton, not finished tampons, and neither Tampon Tribe nor Cohitech posts the GOTS certificate number, so the certification rests on Cohitech’s public statement plus that report; ayna will link the certificate once it’s provided. Separately, Tampon Tribe calls itself the only totally plastic-free U.S. period product; that’s a marketing claim the certifications don’t cover, and ayna couldn’t verify it."}'::jsonb, 'Organic cotton with no fragrance, dyes, or chlorine bleaching is a reasonable choice for people with vulvar irritation or who want fewer additives. What the evidence doesn’t support is treating "100% organic cotton" as a TSS safety upgrade: FDA’s guidance focuses on using the lowest absorbency you need and changing every 4 to 8 hours, and a 2018 lab study actually found cotton/rayon blend tampons grew less Staphylococcus aureus than cotton-only ones.

Tampon Tribe’s cotton "safety veil" around the core is designed to keep fibers from shedding on removal, a concern with some cotton tampons. No independent study of Tampon Tribe tampons was found.', 'On tampontribe.com, Organic Tampons average 4.6 out of 5 from 401 reviews (reviews on the brand’s own site).', 'Absorbency comes in Regular, Super, and Super Plus. No independent lab comparison of Tampon Tribe tampons against other brands was found.', 'independent', 'ayna synthesis of FDA and ACOG guidance and peer-reviewed research; not a direct clinician quote. Product details are from tampontribe.com.', 'curated', true, false, 4.6, true, '{"userRatingSourceUrl":"https://tampontribe.com/products/tampons","affiliateUrl":"https://www.awin1.com/cread.php?awinmid=91275&awinaffid=3082811&ued=https%3A%2F%2Ftampontribe.com%2Fproducts%2Ftampons%3Fselling_plan%3D626000030%26variant%3D44206457192706","doctorOpinionShort":"A plastic-free, organic cotton tampon with a cardboard applicator. Organic cotton cuts additives but isn’t a proven TSS-risk downgrade; FDA says to use the lowest absorbency and change every 4 to 8 hours. No study of this brand was found.","whoItsFor":["People who want organic cotton tampons with no plastic, fragrance, or dyes","Anyone who wants a cardboard applicator instead of plastic","Subscription shoppers who want a customizable monthly box with free U.S. delivery"],"howToUse":{"intro":"Per Tampon Tribe’s directions and FDA tampon guidance:","steps":["Unwrap the paper wrap.","Twist the top part of the applicator in the opposite direction from the base.","Push the base up slightly so the tip of the tampon shows, then insert.","Choose the lowest absorbency that handles your flow, and change every 4 to 8 hours; never longer than 8 hours (FDA)."],"sourceUrl":"https://tampontribe.com/products/tampons","sourceLabel":"tampontribe.com: Organic Tampons"},"warnings":["Toxic shock syndrome (TSS) is rare but serious. Remove the tampon and get emergency care for sudden high fever, vomiting, diarrhea, dizziness or fainting, or a sunburn-like rash during your period (FDA).","Use only during your period, with the lowest absorbency you need.","Not a form of contraception and does not protect against STIs."],"integrations":[],"badges":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.fda.gov/consumers/consumer-updates/facts-tampons-and-tampon-safety","text":"FDA: Tampon Safety Facts","summary":"FDA advises using the lowest absorbency tampon you need, changing every 4 to 8 hours and never wearing one longer than 8 hours, and knowing the signs of toxic shock syndrome (sudden high fever, vomiting, diarrhea, fainting or dizziness, or a sunburn-like rash). FDA also notes cleared tampons are made of cotton, rayon, or blends, bleached without elemental chlorine. This is category guidance, not validation of a specific product."},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5981080/","text":"Impact of currently marketed tampons and menstrual cups on S. aureus growth and TSST-1 production in vitro (Nonfoux et al., 2018)","summary":"In a lab study of 11 tampon types, tampons made of a cotton/rayon mix grew less Staphylococcus aureus than cotton-only tampons. It suggests \"100% cotton\" isn’t automatically lower TSS risk; absorbency and wear time matter more. Lab evidence, not a study of Tampon Tribe tampons."},{"url":"https://tampontribe.com/blogs/news/our-third-party-testing-and-certifications","text":"Tampon Tribe: Third-Party Testing and Certifications","summary":"Tampon Tribe’s testing page, linking its June 2024 independent lab analysis (CALITEC LAB, Barcelona) of its organic cotton: glyphosate and AMPA below 0.01 mg/kg, no multi-residue pesticides detected, GMO-negative, residual chlorine below 0.1 mg/L, formaldehyde below 0.01 mg/kg, and 9 heavy metals (including arsenic, lead, mercury, and cadmium) below detection limits. This tested a sample of raw organic cotton from manufacturer Cohitech, not finished products, and isn’t a clinical study."},{"url":"https://www.cohitech.net/en/","text":"Cohitech (Cotton High Tech): manufacturer certifications","summary":"Tampon Tribe’s manufacturer, the Spanish organic cotton producer named on its lab report. Cohitech states its products are certified organic under GOTS by ICEA and by Cotton Inc., that it is FDA-registered with ISO 13485/MDSAP medical-device quality certification, and that products are dermatologically tested by independent labs as hypoallergenic and non-irritating. Its site doesn’t post the GOTS certificate number."}]},"community":{"links":[{"url":"https://tampontribe.com/products/tampons","text":"tampontribe.com: Organic Tampons reviews","summary":"The brand’s product page: 4.6/5 from 401 reviews as of September 30, 2026."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-organic-pads', 'Tampon Tribe Organic Pads', 'Tampon Tribe', 'pad', 'physical', 'Thin, winged pads made with certified organic cotton and no plastic. Day pads are 240 mm long with 100 ml absorbency; Night pads are 290 mm with 120 ml absorbency and double wings. "Gravity" anti-leak edges help keep you dry. Individually wrapped, with a plant-based backing and a vegan biopolymer adhesive instead of glue. Sold as a monthly subscription with free U.S. delivery.', '$10.60 per box of 10, as a monthly subscription (Day, Night, or 7 Day + 3 Night)', '/products/tampon-tribe/organic-pads.webp', 'https://tampontribe.com/products/pads', '["organic","sustainability","comfort"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Menstrual pads are regulated by the FDA as medical devices; tampontribe.com doesn’t list this product’s FDA details. The manufacturer, Cohitech, is FDA-registered and certified to ISO 13485 (medical-device quality management).","materials":"100% organic cotton top layer and absorbent core (certified organic under GOTS by ICEA). No superabsorbent gel, perfume, dyes, or glue; plant-based backing with a vegan biopolymer adhesive. Vegan and hypoallergenic. Individually wrapped.","recalls":"No recalls are mentioned on tampontribe.com; check current FDA and manufacturer recall notices.","allergens":"Hypoallergenic (independently dermatologist-tested, per manufacturer Cohitech), fragrance-free, dye-free, and vegan.","sideEffects":"None expected. Stop using if you notice irritation. Full notes are listed below.","opinionAlerts":"Without superabsorbent gel, these rely on cotton alone, so they may need changing more often on heavy days. Certification and testing: Tampon Tribe’s manufacturer, Cohitech (Spain), states its products are certified organic under GOTS by ICEA, and a June 2024 independent lab report (CALITEC LAB, Barcelona) found no pesticide residues, glyphosate, GMOs, formaldehyde, or detectable heavy metals in its organic cotton. Two limits: the lab tested a sample of raw organic cotton, not finished pads, and neither Tampon Tribe nor Cohitech posts the GOTS certificate number, so the certification rests on Cohitech’s public statement plus that report; ayna will link the certificate once it’s provided. Separately, Tampon Tribe calls itself the only totally plastic-free U.S. period product; that’s a marketing claim the certifications don’t cover, and ayna couldn’t verify it."}'::jsonb, 'Cotton pads without fragrance, dyes, or plastic top sheets are a sensible choice for people with vulvar irritation or sensitivity to synthetic materials. ACOG’s general advice applies: change a pad at least every 4 to 8 hours, or whenever it feels full or wet. Because they skip superabsorbent gel, they may need changing more often on heavy days. No independent study of these pads was found.', 'On tampontribe.com, Organic Pads average 4.8 out of 5 from 163 reviews (reviews on the brand’s own site).', 'Day pads hold up to 100 ml and Night pads up to 120 ml, per the brand. No independent comparison with other pads was found.', 'independent', 'ayna synthesis of FDA and ACOG guidance and peer-reviewed research; not a direct clinician quote. Product details are from tampontribe.com.', 'curated', false, false, 4.8, true, '{"userRatingSourceUrl":"https://tampontribe.com/products/pads","affiliateUrl":"https://tidd.ly/4zEjNsY","doctorOpinionShort":"Organic cotton, plastic-free pads with wings. A reasonable pick for sensitive skin; change every 4 to 8 hours per ACOG. No study of this brand was found.","whoItsFor":["People with vulvar irritation or sensitivity to plastic or synthetic pad materials","Anyone who wants plastic-free, organic cotton pads","Light to moderate flow (Day) and overnight use (Night)"],"howToUse":{"intro":"Per ACOG’s general pad guidance:","steps":["Peel off the backing and press the pad into your underwear, folding the wings around the edges.","Change at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable.","Wrap the used pad and put it in the trash. Tampon Tribe says the pads will biodegrade, but it doesn’t recommend flushing them."],"sourceUrl":"https://www.acog.org/womens-health/faqs/your-first-period","sourceLabel":"ACOG: Your First Period"},"warnings":["Don’t flush; Tampon Tribe itself doesn’t recommend it.","Stop using if you notice irritation or a rash."],"integrations":[],"badges":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.acog.org/womens-health/faqs/your-first-period","text":"ACOG: Your First Period","summary":"ACOG advises changing a pad at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable, and explains how pads with wings stay in place. General guidance for any pad, not validation of a specific product."},{"url":"https://tampontribe.com/blogs/news/our-third-party-testing-and-certifications","text":"Tampon Tribe: Third-Party Testing and Certifications","summary":"Tampon Tribe’s testing page, linking its June 2024 independent lab analysis (CALITEC LAB, Barcelona) of its organic cotton: glyphosate and AMPA below 0.01 mg/kg, no multi-residue pesticides detected, GMO-negative, residual chlorine below 0.1 mg/L, formaldehyde below 0.01 mg/kg, and 9 heavy metals (including arsenic, lead, mercury, and cadmium) below detection limits. This tested a sample of raw organic cotton from manufacturer Cohitech, not finished products, and isn’t a clinical study."},{"url":"https://www.cohitech.net/en/","text":"Cohitech (Cotton High Tech): manufacturer certifications","summary":"Tampon Tribe’s manufacturer, the Spanish organic cotton producer named on its lab report. Cohitech states its products are certified organic under GOTS by ICEA and by Cotton Inc., that it is FDA-registered with ISO 13485/MDSAP medical-device quality certification, and that products are dermatologically tested by independent labs as hypoallergenic and non-irritating. Its site doesn’t post the GOTS certificate number."}]},"community":{"links":[{"url":"https://tampontribe.com/products/pads","text":"tampontribe.com: Organic Pads reviews","summary":"The brand’s product page: 4.8/5 from 163 reviews as of September 30, 2026."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-pantyliners-bulk-buy', 'Tampon Tribe Organic Pantyliners Bulk Buy (48)', 'Tampon Tribe', 'pad', 'physical', 'A one-time bulk pack of 48 ultrathin organic cotton pantyliners in a jute bag. Each liner is individually wrapped in a starch film (not plastic) and uses a biodegradable polymer adhesive. No perfume, superabsorbent, or chlorine bleaching. The same liners are also sold as a subscription (24 or 48 per box).', '$20 for 48 pantyliners (one-time purchase)', '/products/tampon-tribe/pantyliners-bulk-buy.webp', 'https://tampontribe.com/products/organic-pantyliners-bulk-buy', '["organic","sustainability","comfort","cost"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Pantyliners are regulated by the FDA as medical devices; tampontribe.com doesn’t list this product’s FDA details. The manufacturer, Cohitech, is FDA-registered and certified to ISO 13485 (medical-device quality management).","materials":"100% organic cotton absorbent core (certified organic under GOTS by ICEA) with a cotton non-woven top sheet designed not to leave fibers on skin; individually wrapped in starch film; biodegradable polymer adhesive strip. Perfume-free, superabsorbent-free, no chlorine or dioxin bleaching.","recalls":"No recalls are mentioned on tampontribe.com; check current FDA and manufacturer recall notices.","allergens":"Hypoallergenic (independently dermatologist-tested, per manufacturer Cohitech), fragrance-free, and vegan.","sideEffects":"None expected. Stop using if you notice irritation.","opinionAlerts":"For light days, discharge, or backup only; not enough for a full period. Certification and testing: Tampon Tribe’s manufacturer, Cohitech (Spain), states its products are certified organic under GOTS by ICEA, and a June 2024 independent lab report (CALITEC LAB, Barcelona) found no pesticide residues, glyphosate, GMOs, formaldehyde, or detectable heavy metals in its organic cotton. Two limits: the lab tested a sample of raw organic cotton, not finished pantyliners, and neither Tampon Tribe nor Cohitech posts the GOTS certificate number, so the certification rests on Cohitech’s public statement plus that report; ayna will link the certificate once it’s provided. Separately, Tampon Tribe calls itself the only totally plastic-free U.S. period product; that’s a marketing claim the certifications don’t cover, and ayna couldn’t verify it."}'::jsonb, 'Fragrance-free cotton liners are a good choice for daily discharge or light spotting, especially for people who react to scented or plastic-topped liners. Change them as they get damp. No independent study of these liners was found.', 'This bulk listing shows no reviews of its own. The same liners’ regular Organic Pantyliners listing averages 4.5 out of 5 from 92 reviews on tampontribe.com.', 'Ultrathin, for light absorbency. No independent comparison with other liners was found.', 'independent', 'ayna synthesis of FDA and ACOG guidance and peer-reviewed research; not a direct clinician quote. Product details are from tampontribe.com.', 'curated', false, false, null, true, '{"doctorOpinionShort":"Unscented organic cotton liners for light days and discharge. A sensible choice for sensitive skin; no study of this brand was found.","whoItsFor":["Daily discharge, spotting, or light days","Backup with a tampon or cup","People who react to scented or plastic-topped liners"],"howToUse":{"intro":"General guidance:","steps":["Unwrap, peel off the backing, and press into your underwear.","Change whenever it feels damp, and at least every 4 to 8 hours (ACOG’s pad guidance).","Throw used liners in the trash; don’t flush."],"sourceUrl":"https://www.acog.org/womens-health/faqs/your-first-period","sourceLabel":"ACOG: Your First Period"},"warnings":["For light flow or discharge only; use a pad or tampon for your period.","Stop using if you notice irritation."],"integrations":[],"badges":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.acog.org/womens-health/faqs/your-first-period","text":"ACOG: Your First Period","summary":"ACOG advises changing a pad at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable, and explains how pads with wings stay in place. General guidance for any pad, not validation of a specific product."},{"url":"https://tampontribe.com/blogs/news/our-third-party-testing-and-certifications","text":"Tampon Tribe: Third-Party Testing and Certifications","summary":"Tampon Tribe’s testing page, linking its June 2024 independent lab analysis (CALITEC LAB, Barcelona) of its organic cotton: glyphosate and AMPA below 0.01 mg/kg, no multi-residue pesticides detected, GMO-negative, residual chlorine below 0.1 mg/L, formaldehyde below 0.01 mg/kg, and 9 heavy metals (including arsenic, lead, mercury, and cadmium) below detection limits. This tested a sample of raw organic cotton from manufacturer Cohitech, not finished products, and isn’t a clinical study."},{"url":"https://www.cohitech.net/en/","text":"Cohitech (Cotton High Tech): manufacturer certifications","summary":"Tampon Tribe’s manufacturer, the Spanish organic cotton producer named on its lab report. Cohitech states its products are certified organic under GOTS by ICEA and by Cotton Inc., that it is FDA-registered with ISO 13485/MDSAP medical-device quality certification, and that products are dermatologically tested by independent labs as hypoallergenic and non-irritating. Its site doesn’t post the GOTS certificate number."}]},"community":{"links":[{"url":"https://tampontribe.com/products/organic-pantyliners-bulk-buy","text":"tampontribe.com: Organic Pantyliners Bulk Buy","summary":"The brand’s bulk-buy page."},{"url":"https://tampontribe.com/products/pantyliners","text":"tampontribe.com: Organic Pantyliners reviews","summary":"The same liners’ subscription listing: 4.5/5 from 92 reviews as of September 30, 2026."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-reusable-pads', 'Tampon Tribe Reusable Pads, Organic Cotton (2-Pack)', 'Tampon Tribe', 'pad', 'physical', 'Washable cloth pads made with ultra-soft certified organic cotton, sold in a 2-pack. Rated for medium flow, holding up to 3 tampons’ worth; change more often on heavy days. Three layers with odor control, a super-absorbent inner layer, "gravity" leak-guard edges, and V-shaped straps that fasten with a metal clasp behind your underwear. The brand says they’re PFAS-free, plant-based, and vegan, and offers a money-back guarantee.', '$16.80 for 2 pads', '/products/catalog/p-tampontribe-reusable-pads.webp', 'https://tampontribe.com/products/reusable-pads-2-pack', '["organic","sustainability","reusable","cost"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Reusable menstrual pads are regulated by the FDA as medical devices; tampontribe.com doesn’t list this product’s FDA details.","materials":"Organic cotton top layer, 3-layer construction with an odor-control layer and an absorbent inner layer; V-shaped straps with a metal clasp. PFAS-free, plant-based, and vegan, per the brand.","recalls":"No recalls are mentioned on tampontribe.com; check current FDA and manufacturer recall notices.","allergens":"Hypoallergenic, per the brand.","sideEffects":"None expected with proper washing. Stop using if you notice irritation.","opinionAlerts":"The absorbent layer’s material isn’t specified, and the site calls the product plastic-free. Tampon Tribe publishes GOTS/ICEA certification (through its manufacturer Cohitech) and a June 2024 lab report for its organic cotton, but that lab tested raw cotton for the disposable line, not these cloth pads, and the GOTS certificate number isn’t posted; ayna will link the certificate once it’s provided. The PFAS-free claim specific to these reusable pads isn’t covered by that testing, and ayna couldn’t verify it. Tampon Tribe also calls itself the only totally plastic-free U.S. period product; that’s a marketing claim the certifications don’t cover."}'::jsonb, 'Washable cloth pads are a reasonable, lower-waste option for light to medium flow and for people sensitive to disposable pad materials. The key is hygiene: change them as often as a disposable pad (ACOG suggests every 4 to 8 hours), and wash and fully dry them between uses. The "PFAS-free" claim is the brand’s own, without published test results. No independent study of these pads was found.', 'No customer rating is shown for this pad on tampontribe.com. The brand offers a money-back guarantee if you’re unhappy with it.', 'Holds up to about 3 tampons’ worth, per the brand. No independent absorbency or PFAS test was found.', 'independent', 'ayna synthesis of FDA and ACOG guidance and peer-reviewed research; not a direct clinician quote. Product details are from tampontribe.com.', 'curated', false, false, null, true, '{"affiliateUrl":"https://tidd.ly/4hTD188","doctorOpinionShort":"Organic cotton cloth pads for medium flow. Lower waste and gentle on sensitive skin if washed and dried well between uses. PFAS-free claim is the brand’s own; no study of these pads was found.","whoItsFor":["Light to medium flow, or backup","People who want to cut disposable waste","People sensitive to disposable pad materials"],"howToUse":{"intro":"Per Tampon Tribe’s directions:","steps":["Place the pad in your underwear and fasten the metal clasp behind your underwear.","Change at least every 4 to 8 hours, or sooner on heavy days (it holds about 3 tampons’ worth).","Rinse in cold water, wash with gentle soap, and hang to dry completely before reusing."],"sourceUrl":"https://tampontribe.com/products/reusable-pads-2-pack","sourceLabel":"tampontribe.com: Reusable Pads"},"warnings":["Wash and dry completely between uses to avoid irritation and odor.","For medium flow; change more often, or pair with another product, on heavy days."],"integrations":[],"badges":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.acog.org/womens-health/faqs/your-first-period","text":"ACOG: Your First Period","summary":"ACOG advises changing a pad at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable, and explains how pads with wings stay in place. General guidance for any pad, not validation of a specific product."},{"url":"https://tampontribe.com/blogs/news/our-third-party-testing-and-certifications","text":"Tampon Tribe: Third-Party Testing and Certifications","summary":"Tampon Tribe’s testing page, linking its June 2024 independent lab analysis (CALITEC LAB, Barcelona) of its organic cotton: glyphosate and AMPA below 0.01 mg/kg, no multi-residue pesticides detected, GMO-negative, residual chlorine below 0.1 mg/L, formaldehyde below 0.01 mg/kg, and 9 heavy metals (including arsenic, lead, mercury, and cadmium) below detection limits. This tested a sample of raw organic cotton from manufacturer Cohitech, not finished products, and isn’t a clinical study."}]},"community":{"links":[{"url":"https://tampontribe.com/products/reusable-pads-2-pack","text":"tampontribe.com: Reusable Pads (2-Pack)","summary":"The brand’s product page, with care instructions and its money-back guarantee."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-teen-pads', 'Tampon Tribe Organic Teen Pads', 'Tampon Tribe', 'pad', 'physical', 'Smaller winged pads made for teens and tweens, sized to fit smaller bodies and underwear: 7.2 inches long with 40 ml absorbency. Made with certified organic cotton and no plastic, fragrance, or dyes, with "gravity" anti-leak edges. Individually wrapped, and available individually boxed so they’re easy to keep in a school bag.', '$10 for 18 pads (individually boxed, or in a jute bag)', '/products/tampon-tribe/organic-teen-pads.webp', 'https://tampontribe.com/products/organic-teen-pads', '["organic","sustainability","comfort","beginner-friendly"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Menstrual pads are regulated by the FDA as medical devices; tampontribe.com doesn’t list this product’s FDA details. The manufacturer, Cohitech, is FDA-registered and certified to ISO 13485 (medical-device quality management).","materials":"Certified organic cotton (GOTS, certified by ICEA). No superabsorbent gel, perfume, dyes, or glue; plant-based backing with a vegan biopolymer adhesive. Vegan and hypoallergenic. Individually wrapped; optional individual boxes.","recalls":"No recalls are mentioned on tampontribe.com; check current FDA and manufacturer recall notices.","allergens":"Hypoallergenic (independently dermatologist-tested, per manufacturer Cohitech), fragrance-free, dye-free, and vegan.","sideEffects":"None expected. Stop using if you notice irritation.","opinionAlerts":"At 40 ml, these are for lighter days; heavier flow may need a full-size pad. Certification and testing: Tampon Tribe’s manufacturer, Cohitech (Spain), states its products are certified organic under GOTS by ICEA, and a June 2024 independent lab report (CALITEC LAB, Barcelona) found no pesticide residues, glyphosate, GMOs, formaldehyde, or detectable heavy metals in its organic cotton. Two limits: the lab tested a sample of raw organic cotton, not finished pads, and neither Tampon Tribe nor Cohitech posts the GOTS certificate number, so the certification rests on Cohitech’s public statement plus that report; ayna will link the certificate once it’s provided. Separately, Tampon Tribe calls itself the only totally plastic-free U.S. period product; that’s a marketing claim the certifications don’t cover, and ayna couldn’t verify it."}'::jsonb, 'Smaller, unscented cotton pads are a gentle way to start, since first periods are often irregular and lighter pads fit younger bodies better. ACOG’s advice for first periods applies: change a pad at least every 4 to 8 hours, or whenever it feels full or wet. Very heavy periods (soaking a pad every hour or two) are worth mentioning to a doctor. No independent study of these pads was found.', 'No customer rating is shown for the teen pads on tampontribe.com. Tampon Tribe’s regular Organic Pads average 4.8/5 from 163 reviews on its site.', 'Holds up to 40 ml, per the brand. No independent comparison with other teen pads was found.', 'independent', 'ayna synthesis of FDA and ACOG guidance and peer-reviewed research; not a direct clinician quote. Product details are from tampontribe.com.', 'curated', false, false, null, true, '{"affiliateUrl":"https://tidd.ly/4k3ndRp","doctorOpinionShort":"Teen-sized, unscented organic cotton pads for lighter flow. Change every 4 to 8 hours per ACOG. No study of this brand was found.","whoItsFor":["Teens and tweens starting their periods","Anyone with a smaller body or lighter flow who finds standard pads bulky","Keeping a discreet pad in a school bag"],"howToUse":{"intro":"Per ACOG’s first-period guidance:","steps":["Peel off the backing, press the pad into your underwear, and fold the wings around the edges.","Change at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable.","Wrap the used pad and put it in the trash; don’t flush."],"sourceUrl":"https://www.acog.org/womens-health/faqs/your-first-period","sourceLabel":"ACOG: Your First Period"},"warnings":["Lighter absorbency (40 ml): switch to a larger pad on heavy days.","Stop using if you notice irritation or a rash."],"integrations":[],"badges":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.acog.org/womens-health/faqs/your-first-period","text":"ACOG: Your First Period","summary":"ACOG advises changing a pad at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable, and explains how pads with wings stay in place. General guidance for any pad, not validation of a specific product."},{"url":"https://tampontribe.com/blogs/news/our-third-party-testing-and-certifications","text":"Tampon Tribe: Third-Party Testing and Certifications","summary":"Tampon Tribe’s testing page, linking its June 2024 independent lab analysis (CALITEC LAB, Barcelona) of its organic cotton: glyphosate and AMPA below 0.01 mg/kg, no multi-residue pesticides detected, GMO-negative, residual chlorine below 0.1 mg/L, formaldehyde below 0.01 mg/kg, and 9 heavy metals (including arsenic, lead, mercury, and cadmium) below detection limits. This tested a sample of raw organic cotton from manufacturer Cohitech, not finished products, and isn’t a clinical study."},{"url":"https://www.cohitech.net/en/","text":"Cohitech (Cotton High Tech): manufacturer certifications","summary":"Tampon Tribe’s manufacturer, the Spanish organic cotton producer named on its lab report. Cohitech states its products are certified organic under GOTS by ICEA and by Cotton Inc., that it is FDA-registered with ISO 13485/MDSAP medical-device quality certification, and that products are dermatologically tested by independent labs as hypoallergenic and non-irritating. Its site doesn’t post the GOTS certificate number."}]},"community":{"links":[{"url":"https://tampontribe.com/products/organic-teen-pads","text":"tampontribe.com: Organic Teen Pads","summary":"The brand’s product page."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-tampons-bulk-buy', 'Tampon Tribe Organic Tampons Bulk Buy', 'Tampon Tribe', 'tampon', 'physical', 'A one-time bulk bag of Tampon Tribe''s certified organic cotton tampons: 24 to 28 per bag, in one absorbency or a mix, delivered in an up-cycled jute bag. Same tampons as the subscription: GOTS and ICEA certified organic cotton, a biodegradable cardboard "twist" applicator with a rounded tip, and a safety layer around the core that the brand says keeps fibers from being left behind. No plastic, viscose, perfume, superabsorbents or chlorine bleaching. No subscription needed.', '$20 one-time purchase (28 Regular, 28 Super, 24 Super Plus, Day + Night 16 Regular + 12 Super Plus, or Mixed 16 Regular + 6 Super + 6 Super Plus)', '/products/tampon-tribe/tampons-bulk-buy.webp', 'https://tampontribe.com/products/organic-tampons-bulk-buy', '["organic","sustainability","comfort","heavy-flow"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Tampons are regulated by the FDA as medical devices; tampontribe.com doesn’t list this product’s FDA clearance details. The manufacturer, Cohitech, is FDA-registered and certified to ISO 13485 (medical-device quality management).","materials":"100% organic cotton absorbent core and cover (certified organic under GOTS by ICEA) with an organic cotton safety veil around the core; biodegradable cardboard twist applicator with a rounded tip; paper wrapper. No superabsorbents, glue, rayon/viscose, perfume, or chlorine/dioxin bleaching.","recalls":"No recalls are mentioned on tampontribe.com; check current FDA and manufacturer recall notices.","allergens":"Hypoallergenic (independently dermatologist-tested, per manufacturer Cohitech), fragrance-free, dye-free, and vegan.","sideEffects":"Toxic shock syndrome (TSS) is rare but serious with any tampon: use the lowest absorbency you need and never wear one longer than 8 hours. Full warnings are listed below.","opinionAlerts":"Organic cotton avoids fragrance, dyes, and chlorine bleaching, but \"100% cotton\" isn’t automatically lower TSS risk: a 2018 lab study found cotton/rayon blend tampons grew less S. aureus than cotton-only ones. Absorbency and wear time matter most (FDA). Certification and testing: Tampon Tribe’s manufacturer, Cohitech (Spain), states its products are certified organic under GOTS by ICEA, and a June 2024 independent lab report (CALITEC LAB, Barcelona) found no pesticide residues, glyphosate, GMOs, formaldehyde, or detectable heavy metals in its organic cotton. Two limits: the lab tested a sample of raw organic cotton, not finished tampons, and neither Tampon Tribe nor Cohitech posts the GOTS certificate number, so the certification rests on Cohitech’s public statement plus that report; ayna will link the certificate once it’s provided. Separately, Tampon Tribe calls itself the only totally plastic-free U.S. period product; that’s a marketing claim the certifications don’t cover, and ayna couldn’t verify it."}'::jsonb, 'Organic cotton with no fragrance, dyes, or chlorine bleaching is a reasonable choice for people with vulvar irritation or who want fewer additives. What the evidence doesn’t support is treating "100% organic cotton" as a TSS safety upgrade: FDA’s guidance focuses on using the lowest absorbency you need and changing every 4 to 8 hours, and a 2018 lab study actually found cotton/rayon blend tampons grew less Staphylococcus aureus than cotton-only ones.

Tampon Tribe’s cotton "safety veil" around the core is designed to keep fibers from shedding on removal, a concern with some cotton tampons. No independent study of Tampon Tribe tampons was found.', 'Reviews for these tampons are on the regular Organic Tampons listing: 4.6 out of 5 from 401 reviews on tampontribe.com (as of September 30, 2026).', 'Same tampons as the subscription, in Regular, Super and Super Plus. No independent lab comparison of Tampon Tribe tampons against other brands was found.', 'independent', 'ayna synthesis of FDA and ACOG guidance and peer-reviewed research; not a direct clinician quote. Product details are from tampontribe.com.', 'curated', true, false, null, true, '{"affiliateUrl":"https://tidd.ly/481nNrK","doctorOpinionShort":"A plastic-free, organic cotton tampon with a cardboard applicator. Organic cotton cuts additives but isn’t a proven TSS-risk downgrade; FDA says to use the lowest absorbency and change every 4 to 8 hours. No study of this brand was found.","whoItsFor":["People who want organic cotton tampons with no plastic, fragrance or dyes","Anyone who prefers to buy in bulk once instead of a monthly subscription","People who want a cardboard applicator instead of plastic"],"howToUse":{"intro":"Per Tampon Tribe’s directions and FDA tampon guidance:","steps":["Unwrap the paper wrap.","Twist the top part of the applicator in the opposite direction from the base.","Push the base up slightly so the tip of the tampon shows, then insert.","Choose the lowest absorbency that handles your flow, and change every 4 to 8 hours; never longer than 8 hours (FDA)."],"sourceUrl":"https://tampontribe.com/products/organic-tampons-bulk-buy","sourceLabel":"tampontribe.com: Organic Tampons Bulk Buy"},"warnings":["Toxic shock syndrome (TSS) is rare but serious. Remove the tampon and get emergency care for sudden high fever, vomiting, diarrhea, dizziness or fainting, or a sunburn-like rash during your period (FDA).","Use only during your period, with the lowest absorbency you need.","Not a form of contraception and does not protect against STIs."],"integrations":[],"badges":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.fda.gov/consumers/consumer-updates/facts-tampons-and-tampon-safety","text":"FDA: Tampon Safety Facts","summary":"FDA advises using the lowest absorbency tampon you need, changing every 4 to 8 hours and never wearing one longer than 8 hours, and knowing the signs of toxic shock syndrome (sudden high fever, vomiting, diarrhea, fainting or dizziness, or a sunburn-like rash). FDA also notes cleared tampons are made of cotton, rayon, or blends, bleached without elemental chlorine. This is category guidance, not validation of a specific product."},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5981080/","text":"Impact of currently marketed tampons and menstrual cups on S. aureus growth and TSST-1 production in vitro (Nonfoux et al., 2018)","summary":"In a lab study of 11 tampon types, tampons made of a cotton/rayon mix grew less Staphylococcus aureus than cotton-only tampons. It suggests \"100% cotton\" isn’t automatically lower TSS risk; absorbency and wear time matter more. Lab evidence, not a study of Tampon Tribe tampons."},{"url":"https://tampontribe.com/blogs/news/our-third-party-testing-and-certifications","text":"Tampon Tribe: Third-Party Testing and Certifications","summary":"Tampon Tribe’s testing page, linking its June 2024 independent lab analysis (CALITEC LAB, Barcelona) of its organic cotton: glyphosate and AMPA below 0.01 mg/kg, no multi-residue pesticides detected, GMO-negative, residual chlorine below 0.1 mg/L, formaldehyde below 0.01 mg/kg, and 9 heavy metals (including arsenic, lead, mercury, and cadmium) below detection limits. This tested a sample of raw organic cotton from manufacturer Cohitech, not finished products, and isn’t a clinical study."},{"url":"https://www.cohitech.net/en/","text":"Cohitech (Cotton High Tech): manufacturer certifications","summary":"Tampon Tribe’s manufacturer, the Spanish organic cotton producer named on its lab report. Cohitech states its products are certified organic under GOTS by ICEA and by Cotton Inc., that it is FDA-registered with ISO 13485/MDSAP medical-device quality certification, and that products are dermatologically tested by independent labs as hypoallergenic and non-irritating. Its site doesn’t post the GOTS certificate number."}]},"community":{"links":[{"url":"https://tampontribe.com/products/organic-tampons-bulk-buy","text":"tampontribe.com: Organic Tampons Bulk Buy","summary":"The brand''s bulk-buy page."},{"url":"https://tampontribe.com/products/tampons","text":"tampontribe.com: Organic Tampons reviews","summary":"The same tampons'' subscription listing: 4.6/5 from 401 reviews as of September 30, 2026."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-pads-bulk-buy', 'Tampon Tribe Organic Pads Bulk Buy (20)', 'Tampon Tribe', 'pad', 'physical', 'A one-time bulk bag of 20 of Tampon Tribe''s ultrathin certified organic cotton pads: 14 Day and 6 Night, in a jute bag. Each pad is individually wrapped in a starch film, not plastic, and uses a biodegradable polymer adhesive. No plastic, perfume, superabsorbents or chlorine bleaching. Same pads as the subscription, with no subscription needed.', '$20 for 20 pads (14 Day + 6 Night), one-time purchase', '/products/tampon-tribe/pads-bulk-buy.webp', 'https://tampontribe.com/products/organic-pads-bulk-buy', '["organic","sustainability","comfort","cost"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Menstrual pads are regulated by the FDA as medical devices; tampontribe.com doesn’t list this product’s FDA details. The manufacturer, Cohitech, is FDA-registered and certified to ISO 13485 (medical-device quality management).","materials":"100% organic cotton top layer and absorbent core (certified organic under GOTS by ICEA). No superabsorbent gel, perfume, dyes, or glue; plant-based backing with a vegan biopolymer adhesive. Vegan and hypoallergenic. Individually wrapped.","recalls":"No recalls are mentioned on tampontribe.com; check current FDA and manufacturer recall notices.","allergens":"Hypoallergenic (independently dermatologist-tested, per manufacturer Cohitech), fragrance-free, dye-free, and vegan.","sideEffects":"None expected. Stop using if you notice irritation. Full notes are listed below.","opinionAlerts":"Without superabsorbent gel, these rely on cotton alone, so they may need changing more often on heavy days. Certification and testing: Tampon Tribe’s manufacturer, Cohitech (Spain), states its products are certified organic under GOTS by ICEA, and a June 2024 independent lab report (CALITEC LAB, Barcelona) found no pesticide residues, glyphosate, GMOs, formaldehyde, or detectable heavy metals in its organic cotton. Two limits: the lab tested a sample of raw organic cotton, not finished pads, and neither Tampon Tribe nor Cohitech posts the GOTS certificate number, so the certification rests on Cohitech’s public statement plus that report; ayna will link the certificate once it’s provided. Separately, Tampon Tribe calls itself the only totally plastic-free U.S. period product; that’s a marketing claim the certifications don’t cover, and ayna couldn’t verify it."}'::jsonb, 'Cotton pads without fragrance, dyes, or plastic top sheets are a sensible choice for people with vulvar irritation or sensitivity to synthetic materials. ACOG’s general advice applies: change a pad at least every 4 to 8 hours, or whenever it feels full or wet. Because they skip superabsorbent gel, they may need changing more often on heavy days. No independent study of these pads was found.', 'Reviews for these pads are on the regular Organic Pads listing: 4.8 out of 5 from 163 reviews on tampontribe.com (as of September 30, 2026).', 'Same pads as the subscription: Day pads hold up to 100 ml and Night pads up to 120 ml, per the brand. No independent comparison with other pads was found.', 'independent', 'ayna synthesis of FDA and ACOG guidance and peer-reviewed research; not a direct clinician quote. Product details are from tampontribe.com.', 'curated', false, false, null, true, '{"affiliateUrl":"https://tidd.ly/4i2KEt3","doctorOpinionShort":"Organic cotton, plastic-free pads with wings. A reasonable pick for sensitive skin; change every 4 to 8 hours per ACOG. No study of this brand was found.","whoItsFor":["People with vulvar irritation or sensitivity to plastic or synthetic pad materials","Anyone who prefers to buy in bulk once instead of a monthly subscription","A mix of day and overnight use"],"howToUse":{"intro":"Per ACOG’s general pad guidance:","steps":["Peel off the backing and press the pad into your underwear, folding the wings around the edges.","Change at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable.","Wrap the used pad and put it in the trash. Tampon Tribe says the pads will biodegrade, but it doesn’t recommend flushing them."],"sourceUrl":"https://www.acog.org/womens-health/faqs/your-first-period","sourceLabel":"ACOG: Your First Period"},"warnings":["Don’t flush; Tampon Tribe itself doesn’t recommend it.","Stop using if you notice irritation or a rash."],"integrations":[],"badges":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.acog.org/womens-health/faqs/your-first-period","text":"ACOG: Your First Period","summary":"ACOG advises changing a pad at least every 4 to 8 hours, or whenever it feels full, wet, or uncomfortable, and explains how pads with wings stay in place. General guidance for any pad, not validation of a specific product."},{"url":"https://tampontribe.com/blogs/news/our-third-party-testing-and-certifications","text":"Tampon Tribe: Third-Party Testing and Certifications","summary":"Tampon Tribe’s testing page, linking its June 2024 independent lab analysis (CALITEC LAB, Barcelona) of its organic cotton: glyphosate and AMPA below 0.01 mg/kg, no multi-residue pesticides detected, GMO-negative, residual chlorine below 0.1 mg/L, formaldehyde below 0.01 mg/kg, and 9 heavy metals (including arsenic, lead, mercury, and cadmium) below detection limits. This tested a sample of raw organic cotton from manufacturer Cohitech, not finished products, and isn’t a clinical study."},{"url":"https://www.cohitech.net/en/","text":"Cohitech (Cotton High Tech): manufacturer certifications","summary":"Tampon Tribe’s manufacturer, the Spanish organic cotton producer named on its lab report. Cohitech states its products are certified organic under GOTS by ICEA and by Cotton Inc., that it is FDA-registered with ISO 13485/MDSAP medical-device quality certification, and that products are dermatologically tested by independent labs as hypoallergenic and non-irritating. Its site doesn’t post the GOTS certificate number."}]},"community":{"links":[{"url":"https://tampontribe.com/products/organic-pads-bulk-buy","text":"tampontribe.com: Organic Pads Bulk Buy","summary":"The brand''s bulk-buy page."},{"url":"https://tampontribe.com/products/pads","text":"tampontribe.com: Organic Pads reviews","summary":"The same pads'' subscription listing: 4.8/5 from 163 reviews as of September 30, 2026."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-pantyliners-subscription', 'Tampon Tribe Organic Pantyliners (subscription)', 'Tampon Tribe', 'pad', 'physical', 'The subscription version of Tampon Tribe''s ultrathin certified organic cotton pantyliners (see the Pantyliners Bulk Buy entry). Pause, change or cancel anytime, with free U.S. delivery, per the brand.', '$10.60 for 24 or $20 for 48, as a subscription', 'https://cdn.shopify.com/s/files/1/0048/6971/8083/products/organic-pantyliners-4568288.jpg?v=1783121130', 'https://tampontribe.com/products/pantyliners', '["organic","sustainability","comfort"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Pantyliners are regulated by the FDA as medical devices; tampontribe.com doesn''t list this product''s FDA details (see the Pantyliners Bulk Buy entry)."}'::jsonb, null, null, null, null, null, 'curated', false, false, null, false, '{"affiliateUrl":"https://tidd.ly/4yYEiAX","isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-menstrual-cup', 'Tampon Tribe Menstrual Cup', 'Tampon Tribe', 'cup', 'physical', 'A reusable menstrual cup made of medical-grade TPE (thermoplastic elastomer) instead of silicone, with no latex, BPA or phthalates; the brand says it is made in Germany and lasts up to 10 years with normal care. Tampon Tribe says TPE warms to body temperature and molds to your shape, and the cup has rounded edges, an easy-grip stem and a patented design meant to reduce leaks and avoid suction on removal. Worn for up to 12 hours depending on flow. Medium (25 mL) is for people under 25 who haven''t given birth vaginally; Large (30 mL) is for everyone else.', '$39.99 (Medium or Large) or $69.99 for both sizes', '/products/tampon-tribe/menstrual-cup.webp', 'https://tampontribe.com/products/menstrual-cup', '["sustainability","cost","comfort","heavy-flow"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Menstrual cups are regulated by the FDA, which requires makers to register and list them and follow good manufacturing practices. Tampon Tribe says its TPE is compliant with FDA, RoHS, REACH and Prop 65 standards; tampontribe.com doesn''t list the cup''s FDA registration details.","materials":"Medical-grade TPE (thermoplastic elastomer). Silicone-free, latex-free, BPA-free and phthalate-free, per the brand. Medium: 25 mL capacity, 43 mm wide, 67 mm long. Large: 30 mL, 46 mm wide, 66 mm long. Recyclable, per the brand.","recalls":"No recalls found.","allergens":"Latex-free and silicone-free, per the brand, which may suit people who react to either.","sideEffects":"A systematic review of cup studies found rare reports of pain or vaginal wounds, rashes or allergies, urinary complaints and toxic shock syndrome. FDA says to stop using a cup and contact your provider if you get itching, a rash, pain, swelling or discomfort. Full warnings are listed below.","opinionAlerts":"Tampon Tribe says the cup is \"endorsed by MDs and leading researchers\" and that TPE is more comfortable than silicone; neither claim is backed by a study on tampontribe.com. Most cup research is on silicone cups, not TPE."}'::jsonb, 'Menstrual cups as a category have reasonable evidence. A 2019 Lancet Public Health review of 43 studies (3,319 people) found cups leaked about the same as or less than pads and tampons, didn''t harm vaginal bacteria, and 73% of users wanted to keep using one. Most people needed a few cycles to get used to inserting and removing it.

The review also logged rare problems: 5 reports of toxic shock syndrome, 13 IUDs dislodged, and a few cases of pain, wounds or rashes. FDA advises talking to your gynecologist before using a cup with an IUD, and emptying and washing it every 8 to 12 hours.

This cup is made of TPE rather than the more common silicone. Tampon Tribe says that makes it softer and more comfortable, but most cup research used silicone cups, and no study of this cup was found.', 'tampontribe.com loads its customer reviews with a script ayna can''t read automatically, so no rating is quoted here; read them on the product page. In the 2019 review of cup studies, 73% of participants wanted to keep using a cup after trying one.', 'No study of this cup was found. For cups in general, a 2019 review of 43 studies found leakage similar to or lower than pads and tampons. Capacity is 25 mL (Medium) or 30 mL (Large), per the brand.', 'independent', 'ayna summary of FDA guidance on menstrual cups and a systematic review of cup studies. Not a direct clinician quote; no study tested this cup.', 'curated', true, false, null, true, '{"affiliateUrl":"https://tidd.ly/4hViLDa","doctorOpinionShort":"Cups leak about as much as or less than pads and tampons and are generally safe (2019 review of 43 studies), with rare TSS and IUD dislodgement. TPE rather than silicone; no study of this cup was found.","doctorOpinionCitations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31324419/","label":"PubMed (NIH): Menstrual cup use, leakage, acceptability and safety, systematic review and meta-analysis (Lancet Public Health, 2019)"},{"url":"https://www.fda.gov/medical-devices/menstrual-product-options-facts-and-safe-use/menstrual-cups","label":"FDA: Menstrual Cups"}],"whoItsFor":["People who want a reusable, lower-waste alternative to tampons and pads","Anyone sensitive to latex or silicone, since this cup is TPE","Medium for under 25 and no vaginal birth; Large for over 25 or after a vaginal birth, per the brand","Have an IUD? Talk to your gynecologist first (FDA)","Not for bleeding after childbirth, or for discharge from an infection (FDA)"],"howToUse":{"intro":"Per FDA guidance and Tampon Tribe''s tips:","steps":["Wash your hands, and wash the cup following the instructions before inserting it (FDA).","Fold the cup and insert it. Tampon Tribe says it should sit a bit lower than a tampon.","To help it open and seal, push the stem up slightly, rotate the cup, or gently squeeze its base. Run a finger around the base to check for folds.","Empty and wash it every 8 to 12 hours; never longer than 12 hours.","At the end of your period, wash it and place it in boiling water for 1 to 2 minutes, or follow the cleaning instructions in the box (FDA)."],"sourceUrl":"https://www.fda.gov/medical-devices/menstrual-product-options-facts-and-safe-use/menstrual-cups","sourceLabel":"FDA: Menstrual Cups"},"warnings":["Toxic shock syndrome has been reported with menstrual cups, though rarely. Remove the cup and get emergency care for sudden high fever, vomiting, a sunburn-like rash or dizziness during your period.","Have an IUD? Talk to your gynecologist first: cups can dislodge an IUD (FDA; the 2019 review found 13 cases).","Not for bleeding after childbirth or for discharge from an infection (FDA).","Stop using it and contact your provider if you get itching, a rash, pain, swelling or discomfort (FDA).","Not a form of contraception and does not protect against STIs."],"ingredients":"Medical-grade TPE (thermoplastic elastomer); no silicone, latex, BPA or phthalates.","scientificCitations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31324419/","text":"Menstrual cup use, leakage, acceptability and safety (Lancet Public Health, 2019)","summary":"Systematic review of 43 studies (3,319 people): cups leaked the same as or less than pads and tampons; rare TSS, IUD dislodgement and injury reports."},{"url":"https://www.fda.gov/medical-devices/menstrual-product-options-facts-and-safe-use/menstrual-cups","text":"FDA: Menstrual Cups","summary":"How to use and clean cups, IUD caution, and when to stop and call a provider."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31324419/","text":"Menstrual cup systematic review (2019)","summary":"43 studies on leakage, acceptability and safety; most used silicone cups.","justification":"Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."},{"url":"https://www.fda.gov/medical-devices/menstrual-product-options-facts-and-safe-use/menstrual-cups","text":"FDA: Menstrual Cups","summary":"Use, cleaning and safety guidance.","justification":"Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."}]},"community":{"links":[{"url":"https://tampontribe.com/products/menstrual-cup","text":"tampontribe.com: Menstrual Cup","summary":"The brand''s product page, with sizes, materials, troubleshooting tips and customer reviews."}]}},"isEmergingBrand":false}'::jsonb),
  ('p-tampontribe-sample', 'Tampon Tribe Sample Pack', 'Tampon Tribe', 'pad', 'physical', 'A one-time sample of Tampon Tribe''s organic cotton products: 6 tampons (Regular, Super, Super Plus), 4 Day pads, 2 Night pads and 4 pantyliners in a jute bag, per the brand.', '$10 including U.S. delivery, one-time', 'https://cdn.shopify.com/s/files/1/0048/6971/8083/products/sample-us-10-3328589.jpg?v=1783121228', 'https://tampontribe.com/products/secret-sample', '["organic"]'::jsonb, '["menstrual-collection"]'::jsonb, '["tampontribe.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Tampons, pads and pantyliners are regulated by the FDA as medical devices; tampontribe.com doesn''t list FDA details for these (see the matching Tampon Tribe entries)."}'::jsonb, null, null, null, null, null, 'curated', false, false, null, false, '{"affiliateUrl":"https://www.awin1.com/cread.php?awinmid=91275&awinaffid=3082811&ued=https%3A%2F%2Ftampontribe.com%2Fproducts%2Fsecret-sample","isEmergingBrand":false}'::jsonb)
